/*
 * A290884  Let S be the sequence generated by these rules: 0 is in S, and if
 *          z is in S, then z * (1+i) and (z-1) * (1+i) + 1 are in S (where i
 *          denotes the imaginary unit), and duplicates are deleted as they
 *          occur; a(n) = the real part of the n-th term of S.
 * https://oeis.org/A290884
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, base, look
 * Formula:   not stated
 * Range:     i8 n <= 10000, i16 n <= 10000, i32 n <= 10000, i64 n <= 10000,
 *            i128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function computes the real part of the n‑th element of the
   sequence defined by the closure under the two transformations
   f(z)=z*(1+i) and g(z)=(z-1)*(1+i)+1.
   It exploits the fact that the breadth–first enumeration of the
   tree yields a simple binary representation of the index: for n>1,
   let m=n-1. The depth d of the node is
       d = floor_log2(m) + 1
   and the path from the root is the binary expansion of m starting
   with a leading 1.  Each 0 bit corresponds to applying f, each 1
   bit to applying g.  The real part is updated by the recurrence
   a' = a - b, where a,b are the current real and imaginary parts. */
#include <stddef.h>  /* for size_t, NULL */
#include <stdint.h>  /* for uint64_t */

static int floor_log2_u64(idx_t v)
{
    int r = 0;
    while (v >>= 1) ++r;
    return r;         /* v≥1 when called */
}

seq_t a(idx_t n)
{
    if (n == (idx_t)1) return (seq_t)0;

    idx_t m = n - (idx_t)1;          /* m in [1, 2^64-2] */
    int d = floor_log2_u64(m) + 1;   /* depth of the node */

    /* offset = m - 2^(d-1) contains the remaining d-1 bits of the path */
    idx_t pow2 = ((idx_t)1) << (d - 1);
    idx_t offset = m - pow2;

    /* init at root z=0+i*0 */
    seq_t a_re = (seq_t)0;
    seq_t a_im = (seq_t)0;

    /* first implicit bit is always 1 -> apply g */
    seq_t tmp_re = a_re - a_im;
    seq_t tmp_im = a_re - (seq_t)1 + a_im;
    a_re = tmp_re; a_im = tmp_im;

    /* process remaining d-1 bits from most significant to least */
    for (int i = d - 2; i >= 0; --i) {
        int bit = (offset >> i) & 1;
        if (bit == 0) {
            /* apply f: z*(1+i) */
            seq_t a1 = a_re - a_im;
            seq_t b1 = a_re + a_im;
            a_re = a1; a_im = b1;
        } else {
            /* apply g: (z-1)*(1+i)+1 */
            seq_t a1 = a_re - a_im;
            seq_t b1 = a_re - (seq_t)1 + a_im;
            a_re = a1; a_im = b1;
        }
    }
    return a_re;
}
